    grid.innerHTML = slice.length ? slice.map(function (p, i) { return A.productCard(p, i); }).join('') : '<div class="empty glass" style="grid-column:1/-1">' + ic('package-search') + '<h3>No products match your filters</h3><p>Try a different keyword or clear some filters.' + (D.products.length ? '' : ' The marketplace is brand new — sellers are being onboarded.') + '</p><button class="btn btn-p btn-sm" style="margin-top:14px" onclick="AW.mkReset()">Clear filters</button></div>';
    var pg = ''; for (var i = 1; i <= pages; i++) pg += '<button class="' + (i === mk.page ? 'on' : '') + '" onclick="AW.mkPage(' + i + ')">' + i + '</button>';
    $('#mkPager').innerHTML = pages > 1 ? '<button onclick="AW.mkPage(' + (mk.page - 1) + ')" ' + (mk.page === 1 ? 'disabled' : '') + '>' + ic('chevron-left') + '</button>' + pg + '<button onclick="AW.mkPage(' + (mk.page + 1) + ')" ' + (mk.page === pages ? 'disabled' : '') + '>' + ic('chevron-right') + '</button>' : '';
