  A.route('terms', function (pg) {
    pg.setAttribute('data-title', 'Terms & Privacy');
    pg.innerHTML = '<div class="p-hero compact"><img class="bg" src="' + IMG + 'bg-farm-3.jpg" alt=""><div class="wrap"><h1>Terms of trade & <em>Privacy</em></h1><p>Plain-language rules for buying and selling on AgricWorld.</p></div></div><section><div class="wrap" style="max-width:860px"><div class="card legal">' +
      '<h3>1. What AgricWorld is</h3><p>AgricWorld is an online marketplace operated from ' + esc(C.address || 'Lagos, Nigeria') + '. Sellers list their own products; AgricWorld provides the platform, payment collection via Paystack, messaging and dispute mediation. Each sale is a contract between buyer and seller.</p>' +
      '<h3>2. Payments</h3><p>Online payments are processed by Paystack (Nigerian cards, bank transfer, USSD) or Stripe (international cards, Apple Pay, Google Pay). AgricWorld never receives or stores card details. An order is marked <b>paid</b> only after the payment provider confirms the transaction. Order requests carry no payment; buyer and seller agree terms directly.</p>' +
      '<h3>3. Delivery</h3><p>Delivery is arranged between buyer and seller unless a listing states otherwise. Delivery costs are not included in listed prices unless stated.</p>' +
      '<h3>4. Problems & refunds</h3><p>Report issues to the seller first. If unresolved within ' + (C.disputeWindowHours || 48) + ' hours of delivery, contact AgricWorld support with your order reference. Where a paid order is cancelled before dispatch, the payment is refunded through Paystack.</p>' +
      '<h3>5. Seller obligations</h3><p>Sellers must list only products they can supply, use genuine photos, keep stock and prices accurate, and respond to buyers promptly. Prohibited: counterfeit inputs, banned agrochemicals, and any listing that breaks Nigerian law.</p>' +
      '<h3>6. Verification</h3><p>The verified badge means AgricWorld has reviewed documents supplied by the business (e.g. CAC registration or ID). It is not a guarantee of performance.</p>' +
      '<h3>7. Privacy</h3><p>We store the account and order information you provide to operate the marketplace, and share buyer contact details with the seller of an order so it can be fulfilled. We do not sell personal data. Email <a href="mailto:' + esc(C.contactEmail || '') + '">' + esc(C.contactEmail || '') + '</a> to access or delete your data.</p>' +
      '<p style="color:var(--text-3);font-size:.82rem;margin-top:20px">Last updated ' + new Date().toLocaleDateString('en-NG', { month: 'long', year: 'numeric' }) + '.</p></div></div></section>';
  });
